import { Schema as S } from "effect"
import { Tool } from "effect/ai"

export const ReserveInventoryTool = Tool.make("reserve_inventory", {
  description: "Reserve warehouse stock for an existing customer order.",
  parameters: {
    orderId: S.String.annotate({
      description: "Identifier of the existing order receiving the reservation."
    }),
    sku: S.String.annotate({
      description: "Exact stock-keeping code of the item to reserve."
    }),
    quantity: S.Int.annotate({
      description: "Number of units requested; must be greater than zero."
    }),
    warehouseId: S.String.annotate({
      description: "Warehouse to reserve from; must serve the order's destination."
    }),
    allowPartial: S.Boolean.pipe(S.optional).annotate({
      description: "Set true to reserve fewer than the requested units if stock is insufficient; defaults to false."
    })
  },
  success: S.Struct({
    reservationId: S.String,
    reservedQuantity: S.Int,
    expiresAt: S.String
  }),
  failure: S.String
})
